SELECT gen.INDX_SNAME AS `指数名称`, mkt.SECCODE AS `指数代码`, '2026-01-01' AS `区间起始日期`, MAX(mkt.TRADEDATE) AS `区间截止日期`, ROUND(AVG(mkt.TVALUE) / 100000000, 2) AS `日均成交额(亿)` FROM GET_INDX_GEN_INFO gen JOIN INDX_MKT mkt ON gen.INNER_CODE = mkt.INNER_CODE WHERE gen.INDX_SNAME LIKE '%中证军工%' AND gen.USE_STATUS = '使用' AND gen.ISVALID = 1 AND mkt.ISVALID = 1 AND mkt.TRADEDATE >= '2026-01-01' AND mkt.TRADEDATE <= '2026-09-02' AND mkt.TVALUE IS NOT NULL GROUP BY gen.INDX_SNAME, mkt.SECCODE;
